                ('script_exemple', models.TextField(blank=True, default='\n# ── Example of a valid Python script (provided for guidance) ──────────────\n# This script illustrates EXACTLY the expected 10-key structure, in order.\n# The model must take inspiration from it for the form, replacing the content with\n# a real analysis computed on the actual data received.\n#\n# KEY RULE: pourquoi / explication / analyse_predictive / conclusion /\n# recommendations are NEVER fixed sentences written in advance.\n# Each one MUST derive from a condition (if/else) evaluated on values\n# actually computed (statistics, KPIs, thresholds). No improvised text.\n\ndef executer(dataframe):\n    import pandas as pd\n    import numpy as np\n    import matplotlib\n    matplotlib.use("Agg")\n    import matplotlib.pyplot as plt\n\n    cols_num = dataframe.select_dtypes(include="number").columns\n    n = len(dataframe)\n\n    # 1. Table statistics (column name -> value)\n    table_statistiques = {}\n    for col in cols_num:\n        table_statistiques[f"{col}_moyenne"] = round(float(dataframe[col].mean()), 2)\n        table_statistiques[f"{col}_total"] = round(float(dataframe[col].sum()), 2)\n        table_statistiques[f"{col}_ecart_type"] = round(float(dataframe[col].std()) if pd.notna(dataframe[col].std()) else 0.0, 2)\n    table_statistiques["nb_lignes"] = n\n    table_statistiques["nb_colonnes"] = len(dataframe.columns)\n\n    # 2. Decision KPIs — condition per column: completeness + variability\n    kpi = {}\n    colonnes_incompletes = []   # < 90% completeness\n    colonnes_instables = []     # coefficient of variation > 0.5\n    for col in cols_num:\n        nb_na = int(dataframe[col].isna().sum())\n        taux_completude = round(100 * (1 - nb_na / max(n, 1)), 1)\n        kpi[f"{col}_taux_completude_pct"] = taux_completude\n        if taux_completude < 90:\n            colonnes_incompletes.append(col)\n        moyenne = dataframe[col].mean()\n        ecart = dataframe[col].std()\n        if moyenne and not pd.isna(moyenne) and moyenne != 0 and ecart and not pd.isna(ecart):\n            if abs(ecart / moyenne) > 0.5:\n                colonnes_instables.append(col)\n    kpi["nb_colonnes_incompletes"] = len(colonnes_incompletes)\n    kpi["nb_colonnes_instables"] = len(colonnes_instables)\n\n    # 3. Figures\n    figures = []\n    if len(cols_num) > 0:\n        col = cols_num[0]\n        figures.append({\n            "type": "hist",\n            "y": [float(v) for v in dataframe[col].dropna().tolist()],\n            "bins": 20,\n            "titre": f"Distribution of {col}",\n        })\n\n    # 4. Texts — EVERY sentence derives from a condition on the values\n    #    computed above (kpi / table_statistiques), never fixed text.\n    titre = f"Decision analysis — {n} record(s)"\n\n    if colonnes_incompletes or colonnes_instables:\n        pourquoi = (\n            f"This analysis is relevant because {len(colonnes_incompletes)} column(s) below 90% "\n            f"completeness and {len(colonnes_instables)} column(s) with high variability were detected: "\n            "monitoring is needed before any decision."\n        )\n    else:\n        pourquoi = (\n            f"This analysis confirms the reliability of the dataset ({n} row(s), all numeric "\n            "columns complete and stable) to support an immediate decision."\n        )\n\n    comment = (\n        f"Computation of descriptive statistics and completeness rate on the {len(cols_num)} "\n        "numeric column(s), then detection of the columns below the 90% completeness threshold "\n        "and of those whose coefficient of variation exceeds 0.5."\n    )\n\n    if colonnes_incompletes:\n        explication = (\n            f"Over {table_statistiques[\'nb_lignes\']} row(s) and {table_statistiques[\'nb_colonnes\']} "\n            f"column(s), the following columns are incomplete (< 90%): {\', \'.join(colonnes_incompletes)}."\n        )\n    else:\n        explication = (\n            f"Over {table_statistiques[\'nb_lignes\']} row(s) and {table_statistiques[\'nb_colonnes\']} "\n            "column(s), no numeric column falls below the 90% completeness threshold."\n        )\n\n    if colonnes_instables:\n        analyse_predictive = (\n            f"The high variability observed on {\', \'.join(colonnes_instables)} indicates a risk of "\n            "increasing dispersion if no action is taken over the coming periods."\n        )\n    else:\n        analyse_predictive = (\n            "The absence of any high-variability column (coefficient of variation ≤ 0.5) suggests a "\n            "stable trend, with no warning signal over the coming periods."\n        )\n\n    if not colonnes_incompletes and not colonnes_instables:\n        conclusion = "The computed indicators are all within the expected thresholds: no urgent corrective action."\n    elif colonnes_incompletes and colonnes_instables:\n        conclusion = "Completeness gaps AND high variability coexist: a priority review is recommended."\n    else:\n        conclusion = "One of the two thresholds (completeness or stability) is exceeded: a targeted check is recommended."\n\n    recommandations = []\n    if colonnes_incompletes:\n        recommandations.append(f"Fill in the missing values on: {\', \'.join(colonnes_incompletes)}.")\n    if colonnes_instables:\n        recommandations.append(f"Investigate the abnormal dispersion on: {\', \'.join(colonnes_instables)}.")\n    if not recommandations:\n        recommandations.append("Maintain the current collection: no completeness or stability threshold is exceeded.")\n\n    return {\n        "titre": titre,\n        "pourquoi": pourquoi,\n        "comment": comment,\n        "table_statistiques": table_statistiques,\n        "figures": figures,\n        "explication": explication,\n        "analyse_predictive": analyse_predictive,\n        "kpi": kpi,\n        "conclusion": conclusion,\n        "recommandations": recommandations,\n    }\n', help_text='Example Python script injected into every dashboard prompt (analysis channel).')),
