                ('modules_autorises_graphique_bi', models.TextField(blank=True, default='pandas, numpy, scipy, matplotlib, matplotlib.pyplot, math, statistics, prophet', help_text='Same principle as modules_autorises_script, but for the GRAPHIQUE_BI channel (BI dashboards): a widget only draws, deliberately restricted base (no sklearn/network).')),
                ('modules_autorises_couche_ontologie', models.TextField(blank=True, default='networkx, math, statistics, collections, itertools', help_text='Same principle as modules_autorises_script, but for the COUCHE_ONTOLOGIE channel (custom layers of the surroundings graph): the script only reads/enriches an already built networkx.DiGraph, no access to raw data is needed.')),
                ('script_exemple_document', models.TextField(blank=True, default='\n# ── Example of a valid document script (provided for guidance) ────────────\n# This script illustrates EXACTLY the 10-key structure expected by the\n# document channel, AND the DYNAMIC DISCOVERY method for the data: it does not\n# reference ANY specific slug hard-coded, it iterates over enregistrement.items() and\n# distinguishes numeric/textual/date by a type test — exactly what the\n# ABSOLUTE RULE requires. It is complete and directly executable as is on\n# any table (no error, no missing key), which makes it\n# a neutral safety net if the model cannot do better.\n# The model must take inspiration from it for the FORM, adapting the actual content\n# (title, lines, totals) to the business meaning of the table described in the SCHEMA.\n\ndef executer(enregistrement):\n    from datetime import date, datetime\n\n    # 1. Dynamic discovery of the fields — no hard-coded key.\n    champs_texte = {}\n    champs_nombre = {}\n    champs_date = {}\n    for cle, valeur in enregistrement.items():\n        if cle in ("id", "matricule", "code_acces_client") or valeur is None:\n            continue\n        if isinstance(valeur, bool):\n            champs_texte[cle] = "Oui" if valeur else "Non"\n        elif isinstance(valeur, (int, float)):\n            champs_nombre[cle] = valeur\n        elif isinstance(valeur, str) and valeur.strip():\n            # Dates arrive as text (YYYY-MM-DD or DD/MM/YYYY): recognized by their format.\n            analysee = None\n            for forme in ("%Y-%m-%d", "%d/%m/%Y"):\n                try:\n                    analysee = datetime.strptime(valeur.strip()[:10], forme)\n                    break\n                except ValueError:\n                    pass\n            if analysee:\n                champs_date[cle] = analysee\n            else:\n                champs_texte[cle] = valeur.strip()\n\n    # 2. Identity — first text value found serves as "name" for lack of\n    #    anything better; failing that, a generic identifier based on the id.\n    identifiant = enregistrement.get("id")\n    premier_texte = next(iter(champs_texte.values()), None)\n    nom_entite = premier_texte or (f"Entity #{identifiant}" if identifiant is not None else "Entity")\n\n    # 3. Lines — one line per numeric field discovered (quantity by\n    #    default 1, the unit price = the value itself).\n    lignes = []\n    for cle, valeur in champs_nombre.items():\n        lignes.append({\n            "description":   cle.replace("_", " ").capitalize(),\n            "quantite":      1,\n            "prix_unitaire": round(float(valeur), 2),\n            "montant":       round(float(valeur), 2),\n        })\n    if not lignes:\n        lignes.append({\n            "description":   "No numeric data available on this record",\n            "quantite":      0,\n            "prix_unitaire": 0.0,\n            "montant":       0.0,\n        })\n\n    sous_total = round(sum(l["montant"] for l in lignes), 2)\n\n    # 4. Date — first date discovered, otherwise today.\n    premiere_date = next(iter(champs_date.values()), None)\n    if isinstance(premiere_date, (date, datetime)):\n        date_document = premiere_date.strftime("%d/%m/%Y")\n    else:\n        date_document = date.today().strftime("%d/%m/%Y")\n\n    # 5. Notes — real condition on the discovered data, never\n    #    fixed text that would not depend on the record.\n    if not champs_nombre and not champs_texte:\n        notes = "Record without usable data: document generated for guidance."\n    elif len(lignes) == 1 and lignes[0]["montant"] == 0.0:\n        notes = "No numeric amount found on this record."\n    else:\n        notes = f"Document generated automatically from {len(champs_nombre)} numeric value(s) and {len(champs_texte)} text value(s)."\n\n    return {\n        "type_document": "autre",\n        "titre":         f"Document — {nom_entite}",\n        "reference":     f"REF-{identifiant}" if identifiant is not None else "REF-0000",\n        "date":          date_document,\n        "emetteur": {\n            "nom":     "",\n            "adresse": "",\n            "contact": "",\n        },\n        "destinataire": {\n            "nom":     nom_entite,\n            "adresse": "",\n            "contact": "",\n        },\n        "lignes": lignes,\n        "totaux": {\n            "sous_total": sous_total,\n            "tva":        0.0,\n            "total":      sous_total,\n        },\n        "notes":     notes,\n        "pied_page": "",\n    }\n', help_text='Example Python script injected into every document prompt (invoice/receipt/quote… channel).')),
                ('role_formule', models.TextField(default='You are a Python expert specialized in writing short calculation formulas for calculation tables (simplified equivalent of an Excel spreadsheet). You receive either one column (pandas.Series) or several columns of a table (pandas.DataFrame), and you write a single function that computes a precise result. You do not talk, you only code.')),
                ('regle_formule', models.TextField(default='ABSOLUTE RULE — FORMULA:\nAnswer ONLY with a Python code block between ```python ... ``` tags, without any text outside these tags.\nThe script must define EXACTLY one function `def formule(cible): ...` that computes and returns the result of the request (a number, a string, a list or a dict — never print, never input).\nNo value or column name hard-coded other than those provided in the CONTEXT: the formula must remain usable if the table changes structure.\nHandle empty or insufficient data cases by returning None rather than raising an exception.\nFORBIDDEN: omitting the `formule` function, changing its signature, adding text outside the code block.')),
                ('contraintes_formule', models.TextField(default='ABSOLUTE PYTHON CONSTRAINTS:\n1. True / False / None. NEVER true / false / null.\n2. NEVER input(), open(), requests, exec(), eval().\n3. Only data source: the `cible` parameter received by `formule(cible)` (pandas.Series or pandas.DataFrame depending on the shape indicated in the CONTEXT).\n4. Allowed modules: see the exact list given below (sandbox specific to the formula channel).\n5. Handle missing values (NaN/None) before any computation — never an unhandled exception: return None if the result cannot be computed.\n6. GENERICITY: no column name must be hard-coded other than those mentioned in the provided CONTEXT.')),
                ('script_exemple_formule_colonne', models.TextField(blank=True, default="def formule(cible):\n    import pandas as pd\n    serie = pd.to_numeric(pd.Series(cible), errors='coerce').dropna()\n    if serie.empty:\n        return None\n    return float(serie.mean())\n", help_text="Example Python script injected into the formula prompt when the target is a single column (pandas.Series) — see FormuleCalcul.cible_type='colonne'.")),
                ('script_exemple_formule_table', models.TextField(blank=True, default="def formule(cible):\n    import pandas as pd\n    df = pd.DataFrame(cible)\n    colonnes_num = [c for c in df.columns if pd.api.types.is_numeric_dtype(df[c])]\n    if not colonnes_num:\n        return None\n    return {c: float(pd.to_numeric(df[c], errors='coerce').sum()) for c in colonnes_num}\n", help_text="Example Python script injected into the formula prompt when the target covers several columns (pandas.DataFrame) — see FormuleCalcul.cible_type='table'.")),
                ('role_graphique_bi', models.TextField(default='You are a Python expert specialized in data visualization with matplotlib, for Power BI-style BI dashboards. You receive either one column (a single dimension) or several columns of a table, and you write a single function that draws ONE clear and readable chart. You do not talk, you only code.')),
                ('regle_graphique_bi', models.TextField(default='ABSOLUTE RULE — BI CHART:\nAnswer ONLY with a Python code block between ```python ... ``` tags, without any text outside these tags.\nThe script must define EXACTLY one function `def dessiner(dataframe, colonnes): ...` that builds a matplotlib figure and RETURNS it (never plt.show()).\n`colonnes` is the ordered list of slugs chosen by the user for THIS widget (in the desired order, e.g. category then value); `dataframe` always contains ALL the columns of the source table, already cast according to their type — the function must use ONLY those listed in `colonnes`, never a hard-coded name.\nAlways fig.tight_layout() before returning, for a clean rendering at any widget size.\nHandle missing/empty columns silently (dropna) rather than raising an exception, so as never to break a widget on a badly entered row.\nFORBIDDEN: omitting the `dessiner` function, changing its signature, calling plt.show(), adding text outside the code block.')),
                ('contraintes_graphique_bi', models.TextField(default='ABSOLUTE PYTHON CONSTRAINTS:\n1. True / False / None. NEVER true / false / null.\n2. NEVER input(), open(), requests, exec(), eval().\n3. Only data source: the `dataframe` parameter received by `dessiner(dataframe, colonnes)`, restricted to the columns listed in `colonnes`.\n4. Allowed modules: see the exact list given below (sandbox specific to the graphique_bi channel — deliberately restricted, a widget only draws, no network access or heavy computation).\n5. Agg backend mandatory (matplotlib.use("Agg") before any pyplot import) and NO plt.show(): the figure is converted to PNG right afterwards by the sandbox.\n6. Handle missing values (NaN/None) before any plotting — never an unhandled exception: dropna rather than crash.\n7. GENERICITY: no column name must be hard-coded other than those received in the `colonnes` parameter.')),
                ('script_exemple_graphique_bi_colonne', models.TextField(blank=True, default='def dessiner(dataframe, colonnes):\n    import matplotlib\n    matplotlib.use("Agg")\n    import matplotlib.pyplot as plt\n    import pandas as pd\n    col = colonnes[0]\n    serie = pd.to_numeric(dataframe[col], errors="coerce").dropna()\n    fig, ax = plt.subplots(figsize=(6, 4))\n    ax.hist(serie, bins=20, color="#4C72B0")\n    ax.set_xlabel(col); ax.set_ylabel("Frequency")\n    fig.tight_layout()\n    return fig\n', help_text="Example Python script injected into the graphique_bi prompt when the target is a single column — see GraphiqueBI.cible_type='colonne_unique'.")),
                ('script_exemple_graphique_bi_multiples', models.TextField(blank=True, default='def dessiner(dataframe, colonnes):\n    import matplotlib\n    matplotlib.use("Agg")\n    import matplotlib.pyplot as plt\n    import pandas as pd\n    if len(colonnes) < 2:\n        fig, ax = plt.subplots(figsize=(6, 4))\n        ax.text(0.5, 0.5, "Choisir une colonne de catégories puis une colonne de valeurs", ha="center")\n        ax.axis("off")\n        return fig\n    cat_col, val_col = colonnes[0], colonnes[1]\n    df = dataframe[[cat_col, val_col]].copy()\n    df[val_col] = pd.to_numeric(df[val_col], errors="coerce")\n    df = df.dropna()\n    fig, ax = plt.subplots(figsize=(6, 4))\n    ax.bar(df[cat_col].astype(str), df[val_col], color="#4C72B0")\n    ax.set_xlabel(cat_col); ax.set_ylabel(val_col)\n    ax.tick_params(axis="x", rotation=45)\n    fig.tight_layout()\n    return fig\n', help_text="Example Python script injected into the graphique_bi prompt when the target covers several columns — see GraphiqueBI.cible_type='colonnes_multiples'.")),
                ('role_couche_ontologie', models.TextField(default='You are a Python expert specialized in enriching graphs with networkx, for the ontology/surroundings graph of a data platform. You receive an already built graph (nodes = tables, documents, AI models, customers, agents... ; edges = relations between them) and you write a single function that adds new nodes and/or new edges representing a requested type of relation or event. You do not talk, you only code.')),
                ('regle_couche_ontologie', models.TextField(default='ABSOLUTE RULE — ONTOLOGY LAYER:\nAnswer ONLY with a Python code block between ```python ... ``` tags, without any text outside these tags.\nThe script must define EXACTLY one function `def etendre(graphe): ...` that receives an already built networkx.DiGraph, enriches it (add_node/add_edge) and RETURNS it (never None).\nEach added node must have a UNIQUE id prefixed by its type (e.g. "fournisseur:1"), a type=str attribute and a label=str attribute; couleur="#rrggbb" and taille=number are optional (by default, a generic color per type/relation is used).\nEach added edge must have a relation=str attribute (the name of the requested relation/event type); couleur="#rrggbb" and poids=number are optional.\nNever delete or modify a node/edge already present in the received graph: the layer only ADDS.\nFORBIDDEN: omitting the `etendre` function, changing its signature, adding text outside the code block.')),
                ('contraintes_couche_ontologie', models.TextField(default='ABSOLUTE PYTHON CONSTRAINTS:\n1. True / False / None. NEVER true / false / null.\n2. NEVER input(), open(), requests, exec(), eval().\n3. Only data source: the `graphe` parameter received by `etendre(graphe)` — no database access, no network access: everything the layer needs (nodes, attributes, existing relations) is already in the received graph.\n4. Allowed modules: see the exact list given below (sandbox specific to the couche_ontologie channel).\n5. Stay fast (the graph is rebuilt at each display): no loops over thousands of iterations, no heavy computation.\n6. GENERICITY: never hard-code a specific node id seen in an example; iterate over `graphe.nodes(data=True)` to dynamically find the relevant nodes (by their `type`, `slug` or `label` attribute).')),
                ('script_exemple_couche_ontologie', models.TextField(blank=True, default='def etendre(graphe):\n    # Walks through the tables already present in the graph (never a hard-coded\n    # id) and adds one node + one relation per table that\n    # matches the requested criterion.\n    for n, attrs in list(graphe.nodes(data=True)):\n        if attrs.get("type") != "table":\n            continue\n        if attrs.get("nb_enregistrements", 0) <= 0:\n            continue\n        nid = f"mon_type:{n}"\n        graphe.add_node(nid, type="mon_type", label=f"Alert — {attrs.get(\'label\', n)}",\n                        couleur="#e74c3c", taille=16)\n        graphe.add_edge(n, nid, relation="ma_relation", couleur="#f59e0b")\n    return graphe\n', help_text='Example Python script injected into every couche_ontologie prompt (ontology channel).')),
                ('role_modele_ia', models.TextField(default='You are a Python expert in machine learning (numpy, scikit-learn) and in deep learning written by hand with numpy. You write a script that adds ONE NEW type of DL or ML model to the training engine of a data platform: a training function and a prediction function. You do not talk, you only code.')),
                ('regle_modele_ia', models.TextField(default='ABSOLUTE RULE — AI MODEL (DL/ML):\nAnswer ONLY with a Python code block between ```python ... ``` tags, without any text outside these tags.\nThe project\'s two engines are scikit-learn (classic ML) and Flax + optax on JAX (deep learning): write the model with the library that matches the request. numpy is only used to prepare the data and store the weights; never rewrite by hand in numpy an algorithm that exists in scikit-learn or Flax.\nThe script defines EXACTLY:\n- NOM: str of the new model type (a-z, 0-9, _ ; 3 to 30 characters; never an already existing type).\n- def entrainer(X, y, ...) -> dict {"weights": {name: numpy.ndarray}, "config": {...}, "accuracy": float}. X: numpy array (rows × already encoded numeric columns); y: one value per row (integer class index for a categorical target, number otherwise). Never assume the number of columns nor the nature of the target (classes or continuous values). lr, epochs, seed and on_epoch are optional: only those declared in the signature receive a value. Each additional hyperparameter (with a default value) appears in the interface.\n- "accuracy" (root of the returned dict) is a PERCENTAGE from 0 to 100; the Trainer converts it to a fraction itself.\n- def predire(weights, config, X) -> numpy.ndarray: reads ONLY weights and config, because the model is saved then reloaded in .gy format: the trained scikit-learn estimator or Flax network no longer exists at inference. predire therefore rebuilds the model identically from weights and config, and entrainer measures the quality of the model BY CALLING predire: inference extends training, it never relies on code or an object that entrainer did not provide. Returns an integer class index per row for a classification, or a numeric value per row.\n  · scikit-learn: store the learned attributes (coef_, intercept_, classes_, ...) in weights as numpy.ndarray; in predire, create the estimator with the same hyperparameters (read from config), reassign these attributes to it, then call .predict().\n  · Flax: describe the architecture in config (layer sizes) and build the network with nn.Sequential([...]) (never a class); store the leaves of the parameter pytree (jax.tree_util.tree_flatten) in weights; in predire, redo modele.init to recover the structure, fill it with the weights, then call modele.apply.\non_epoch(epoch, {"loss": float, "accuracy": float}) is called at each step if provided (accuracy: fraction from 0 to 1); if it returns True, training stops.\nFORBIDDEN: class, file reading/writing, text outside the code block.\nUtility functions (def) defined at script level are allowed; they are used to share the model construction code between entrainer and predire.')),
                ('contraintes_modele_ia', models.TextField(default='ABSOLUTE PYTHON CONSTRAINTS:\n1. True / False / None. NEVER true / false / null.\n2. NEVER input(), open(), requests, exec(), eval(), pickle, joblib; no classes: functions only.\n3. Allowed modules: see the exact list given below (sandbox specific to the modele_ia channel).\n4. No hard-coded data: X and y come from the parameters, never assume a number of columns.\n5. Weights = numpy.ndarray; config = simple Python types (int, float, str, list, dict, bool), because they are reloaded from a .gy file. The scikit-learn estimator or Flax network is never saved as is: only its learned attributes or its parameters, converted to numpy.ndarray.\n6. Reproducible: numpy.random.default_rng(seed); scikit-learn: random_state=seed; Flax: jax.random.PRNGKey(seed).')),
                ('script_exemple_modele_ia', models.TextField(blank=True, default='import numpy\nfrom sklearn.linear_model import LogisticRegression, Ridge\n\nNOM = "sklearn_lineaire"\n\n\ndef _ajuster(Z, y, classification, C):\n    # Entraine l\'estimateur scikit-learn et en extrait ce qui permettra de le reconstruire : ses attributs appris.\n    if classification:\n        m = LogisticRegression(C=C, max_iter=500).fit(Z, y.astype(int))\n        return {"coef": m.coef_, "intercept": m.intercept_, "classes": m.classes_.astype(float)}\n    m = Ridge(alpha=1.0 / C).fit(Z, y)\n    return {"coef": numpy.atleast_2d(m.coef_), "intercept": numpy.atleast_1d(m.intercept_).astype(float)}\n\n\ndef _construire(weights, config):\n    # Reconstruit l\'estimateur ENTRAINE a partir des seuls poids et de la config (rien d\'autre n\'est relu a l\'inference).\n    if config["classification"]:\n        m = LogisticRegression(C=config["C"])\n        m.classes_ = weights["classes"].astype(int)\n        m.coef_, m.intercept_ = weights["coef"], weights["intercept"]\n    else:\n        m = Ridge(alpha=1.0 / config["C"])\n        m.coef_, m.intercept_ = weights["coef"].reshape(-1), float(weights["intercept"][0])\n    return m\n\n\ndef predire(weights, config, X):\n    X = numpy.asarray(X, dtype=float).reshape(len(X), -1)\n    sortie = _construire(weights, config).predict((X - weights["mu"]) / weights["sd"])\n    return sortie.astype(int) if config["classification"] else sortie\n\n\ndef entrainer(X, y, C=1.0, seed=42, on_epoch=None):\n    # X : lignes x colonnes numeriques ; y : une valeur par ligne (indice de classe ou nombre, selon la cible choisie).\n    X = numpy.asarray(X, dtype=float).reshape(len(X), -1)\n    y = numpy.asarray(y).reshape(-1)\n    classification = bool(numpy.all(y == numpy.round(y)))\n    C = float(max(C, 1e-9))\n    mu, sd = X.mean(axis=0), X.std(axis=0) + 1e-9\n    Z = (X - mu) / sd\n    # 20 % des lignes sont mises de cote pour mesurer la qualite du modele.\n    ordre = numpy.random.default_rng(seed).permutation(len(Z))\n    n_test = max(1, len(Z) // 5)\n    test, appr = ordre[:n_test], ordre[n_test:]\n    config = {"C": C, "classification": classification, "n_features": int(Z.shape[1])}\n    # La qualite est mesuree avec predire() : exactement le chemin qu\'empruntera l\'inference sur le modele enregistre.\n    poids = {**_ajuster(Z[appr], y[appr], classification, C), "mu": mu, "sd": sd}\n    pred = predire(poids, config, X[test])\n    if classification:\n        score = float(numpy.mean(pred == y[test]))\n        perte = 1.0 - score\n    else:\n        perte = float(numpy.mean((pred - y[test]) ** 2))\n        score = max(0.0, 1.0 - perte / (float(numpy.var(y[test])) + 1e-9))\n    if on_epoch:\n        on_epoch(0, {"loss": perte, "accuracy": score})\n    # Le modele final est ajuste sur toutes les lignes.\n    poids = {**_ajuster(Z, y, classification, C), "mu": mu, "sd": sd}\n    return {"weights": poids, "config": config, "accuracy": score * 100.0}   # pourcentage (0-100) : le Trainer le ramene a une fraction\n')),
                ('modules_autorises_modele_ia', models.TextField(blank=True, default='numpy, sklearn, math, statistics, json', help_text='Modules importable by an AI model script (sandbox of the MODELE_IA channel).')),
                ('role_tache', models.TextField(default="You are a Python expert specialized in writing autonomous tasks for a data platform: you write a script that runs server-side, either at a given time/interval, or at each data event (new record, relation created, KPI crossed...), and that reads or modifies the company's data, calls AI models, the ontology graph or BI charts. You do not talk, you only code.")),
                ('regle_tache', models.TextField(default='ABSOLUTE RULE (SCHEDULED TASK): Answer ONLY with a complete Python script between ```python ... ``` tags. It defines `executer(contexte=None)` (no `dataframe`) and returns {"resume": str, "fichiers": list} (resume = short report; fichiers = produced paths, [] if none). `contexte` is None for a SCHEDULED task (time/interval). For a CONDITIONAL task (triggered by a data event, see NAME/MODE above), `contexte` is a dict provided AT EACH trigger, containing at least {"categorie": str, "table_id": int|None} and, depending on the category, "enregistrement_id" (int, categories \'enregistrement\'/\'client\'/\'relation\') and/or "champ_id" (category \'relation\'). The SAME script is re-run at each event: NEVER hard-code an id; always read contexte.get("enregistrement_id") and, if present, retrieve the row via `from engine.models import Enregistrement; enr = Enregistrement.objects.get(id=contexte["enregistrement_id"])` then `enr.to_dict()` for its values — handling the case contexte=None or absent key without raising an exception.')),
                ('contraintes_tache', models.TextField(default='ABSOLUTE PYTHON CONSTRAINTS (TASK):\n1. PYTHON ONLY: True / False / None. NEVER true / false / null (JSON).\n2. NO INTERACTIVITY: NEVER input(), sys.stdin. NEVER exec() or eval().\n3. The script runs server-side, without a sandbox: do NOTHING destructive that is not explicitly requested (no deletion of files or records by default).\n4. Data: only via the `engine.models` models described in the context, ALWAYS filtered on the current company (its id is given in the context); never a hard-coded record id.\n5. Robustness: handle `contexte=None` and absent keys without raising an exception; a task that has nothing to do still returns a summary.\n6. Mandatory return: {"resume": str, "fichiers": list}.')),
                ('script_exemple_tache', models.TextField(blank=True, default='from datetime import datetime\n\n# Id of the current company: it is given in the task generation context; fill it in here\n# so that the row read is always that of THIS company.\nENTREPRISE_ID = None\n\n\ndef executer(contexte=None):\n    # SCHEDULED task: contexte is None.\n    # CONDITIONAL task: contexte = {"categorie": ..., "table_id": ..., "enregistrement_id": ...} (depending on the category)\n    contexte = contexte or {}\n    enr_id = contexte.get("enregistrement_id")\n    resume = f"Task executed at {datetime.now():%H:%M}"\n    if enr_id:\n        from engine.models import Enregistrement\n        lignes = Enregistrement.objects.filter(id=enr_id)\n        if ENTREPRISE_ID is not None:\n            lignes = lignes.filter(table__entreprise_id=ENTREPRISE_ID)\n        enr = lignes.first()\n        if enr is not None:\n            resume = f"Record {enr_id} processed ({len(enr.to_dict())} fields)"\n    return {"resume": resume, "fichiers": []}\n')),
                ('modules_autorises_tache', models.TextField(blank=True, default='pandas, numpy, math, statistics, json, datetime', help_text='Modules announced to the AI for a task script (tasks do not run in a sandbox: prompt instruction, not an execution restriction).')),
                ('nom_affichage_document', models.CharField(blank=True, default='', help_text="Company name shown on generated documents. Empty = the company's name.", max_length=200)),
                ('afficher_logo_document', models.BooleanField(default=True, verbose_name='Show the logo on the document')),
                ('position_logo_document', models.CharField(choices=[('gauche', 'Gauche'), ('centre', 'Centre'), ('droite', 'Droite')], default='gauche', max_length=10)),
                ('couleur_accent_document', models.CharField(default='#e8a33d', help_text='Accent color (reference, totals, separators) — #rrggbb format.', max_length=7)),
                ('couleur_entete_document', models.CharField(default='#1f2937', help_text='Background color of the header block — #rrggbb format.', max_length=7)),
                ('couleur_tableau_entete_document', models.CharField(default='#0d1117', help_text='Background color of the line-items table header (invoice/quote) — #rrggbb format.', max_length=7)),
                ('couleur_lignes_alternees_document', models.CharField(default='#f3f4f6', help_text='Background color of the even table rows (zebra effect) — #rrggbb format.', max_length=7)),
                ('couleur_texte_document', models.CharField(default='#1a1a2e', help_text='Main text color (document body) — #rrggbb format.', max_length=7)),
